import sqlite3
db = sqlite3.connect(":memory:")
db.executescript('''
CREATE TABLE orders(id INT, customer TEXT, city TEXT);
INSERT INTO orders VALUES (1,'ravi','Pune'),(2,'ravi','Pune'),(3,'ravi','Pune');
UPDATE orders SET city = 'Mumbai' WHERE id = 3;
''')
print(db.execute('''SELECT customer, COUNT(DISTINCT city)
FROM orders GROUP BY customer''').fetchall())
